class TestVec3f:
    def __init__(self, x, y, z):
        self.data = np.array([x,y,z], dtype=TestVec3NPT)

    def __array__(self, dtype=None):
        return self.data

    @classmethod
    def _from_np_elem(cls, elem):
        if elem.dtype != TestVec3NPT and len(elem) != 3:
            raise ValueError("Bad Element")
        inst = cls.__new__(cls)
        inst.data = elem
        return inst
    
