        if not (self.data.dtype == TestVec3NPT and len(self.data.shape) == 2 and self.data.shape[1] == 3):
            raise ValueError("Could not convert to TestVecBatch")
    
        self.__array_interface__ = self.data.__array_interface__

    def __getitem__(self, key):
        return TestVec3f._from_np_elem(self.data[0])
```

Here's a proof-of-concept struct type:
```python
TestStructNPT = np.dtype([('x', np.int16), ('y', np.int32)])

class TestStruct:
    def __init__(self, x, y):
        self.data = np.void((x,y), TestStructNPT)

    def __scalar__(self, dtype=None):
        return self.data

    @classmethod
    def _from_np_elem(cls, elem):
        if elem.dtype != TestStructNPT:
            raise ValueError("Unexpected type")
        inst = cls.__new__(cls)
        inst.data = elem
        return inst
    
    @property
    def x(self):
        return self.data['x']

    @property
    def y(self):
        return self.data['y']

    def __repr__(self):
        return f"TestStruct(x: {self.x}, y: {self.y})"

class TestStructBatch:
    def __init__(self, data: Sequence[TestStruct] | npt.NDArray):
        if len(data) == 0:
            self.data = np.empty((0,), dtype=TestStructNPT)
        elif isinstance(data, np.ndarray) and data.dtype == TestStructNPT:
            self.data = data
        elif isinstance(data[0], TestStruct):
            self.data = np.array([i.__scalar__() for i in data], dtype=TestStructNPT)
        elif isinstance(data[0], tuple):
            self.data = np.array(data, dtype=TestStructNPT)
        else:
            raise ValueError("Type cannot be converted to records")
            
        if not (self.data.dtype == TestStructNPT and len(self.data.shape) == 1):
            print(self.data)
            raise ValueError("bad data")
        
        self.__array_interface__ = self.data.__array_interface__

    def __getitem__(self, key):
        return TestStruct._from_np_elem(self.data[0])
```

